/**
 * @summary List pharmacy stock inventory
 */
export const getListStockUrl = (params?: ListStockParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/stock?${stringifiedParams}`
    : `/api/stock`;
};

export const listStock = async (
  params?: ListStockParams,
  options?: RequestInit,
): Promise<StockItem[]> => {
  return customFetch<StockItem[]>(getListStockUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListStockQueryKey = (params?: ListStockParams) => {
  return [`/api/stock`, ...(params ? [params] : [])] as const;
};

export const getListStockQueryOptions = <
  TData = Awaited<ReturnType<typeof listStock>>,
  TError = ErrorType<unknown>,
>(
  params?: ListStockParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listStock>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListStockQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listStock>>> = ({
    signal,
  }) => listStock(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listStock>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListStockQueryResult = NonNullable<
  Awaited<ReturnType<typeof listStock>>
>;
export type ListStockQueryError = ErrorType<unknown>;

